# Example graph workflow (ADR-0020). A repository opts in by committing a
# definition as `.enzarb/workflows/issue.yaml` on its default branch.
version: 1
name: issue
on: [issue_opened]            # triggers that create a task
start: prepare
nodes:
  prepare:   {type: command, run: "mise run prepare", optional: true, next: implement}
  implement: {type: agent, prompt: implement, next: {pushed: open_pr, else: failed}}
  open_pr:   {type: action, action: open_change_request, next: done}
  failed:    {type: end, status: failed}
  done:      {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: command, run: x, next: b}
  b: {type: command, run: y, next: a}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: agent, prompt: x, next: m}
  m: {type: action, action: merge_change_request, next: e}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: w
nodes:
  w: {type: wait, events: [comment], next: m}
  m: {type: action, action: merge_change_request, next: e}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: w
nodes:
  w: {type: wait, events: [merge_requested, comment], next: {event == "merge_requested": m, else: e}}
  m: {type: action, action: merge_change_request, next: e}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: w
nodes:
  w: {type: wait, events: [merge_requested], next: e, on_limit: m}
  m: {type: action, action: merge_change_request, next: e}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: w
nodes:
  w: {type: wait, events: [merge_requested], next: m}
  m: {type: action, action: merge_change_request, next: e}
  e: {type: end, status: done}
  f: {type: end, status: failed}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: agent, prompt: fix, next: {"exit_code == 0": e, else: a}, max_visits: 3, on_limit: f}
  e: {type: end, status: done}
  f: {type: end, status: failed}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: command, run: x, next: e}
  spare: {type: command, run: y, next: f}
  e: {type: end, status: done}
  f: {type: end, status: failed}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: wait, events: [comment, approval, ci, review, merge_requested, dependencies_done, timer], from: anyone, next: p}
  p: {type: action, action: post_comment, body: hi, next: o}
  o: {type: action, action: open_change_request, next: e}
  e: {type: end, status: done}
  f: {type: end, status: failed}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: command, run: x, optional: true, next: {true: e, 1: e, else: f}}
  e: {type: end, status: done}
  f: {type: end, status: failed}

version: 1
name: t
on: [issue_opened]
start: a
nodes:
  a: {type: command, run: x}
  a: {type: command, run: y, next: e}
  e: {type: end, status: done}

version: 1
name: t
on: [issue_opened]
start: w
